<script setup lang="ts">
import {ref,computed,onMounted,onBeforeUnmount,watch} from 'vue';
import Modal from '../work/Modal.vue';
import ReportTable from './ReportTable.vue';
import {REPORT_COLUMNS,REPORT_DATES,REPORT_PRESETS,REPORT_SOURCES,newReport,presetReport,reportDate,type ReportConfig,type ReportResult,type ReportTemplate,type ReportJobView,type ReportOptions,type ReportSource} from '~~/shared/types/upts-reports';
import {UPTS_CONTRACT_TYPES} from '~~/shared/types/upts-library';
import {UPTS_WORK_KINDS} from '~~/shared/utils/upts-work-kinds';
import {WORK_STATUSES,type WorkTaskDTO} from '~~/shared/types/work';
const props=defineProps<{initialJobId?:string;filters:Record<string,string|number|undefined>}>();const emit=defineEmits<{close:[];object:[id:number];work:[task:WorkTaskDTO]}>();
const page=ref('catalog'),tab=ref('filter'),config=ref<ReportConfig>(newReport()),options=ref<ReportOptions>({objects:[],people:[],documentTypes:[]}),templates=ref<ReportTemplate[]>([]),jobs=ref<ReportJobView[]>([]),job=ref<ReportJobView|null>(null),preview=ref<ReportResult|null>(null),result=ref<ReportResult|null>(null),error=ref(''),busy=ref(false),previewBusy=ref(false),message=ref(''),saveOpen=ref(false),deleteTarget=ref<ReportTemplate|null>(null),templateName=ref(''),shared=ref(false),selectedTemplate=ref<ReportTemplate|null>(null),attachments=ref(false),savePeriod=ref<ReportConfig['period']>('fixed'),updateExisting=ref(false);
const nav=[['catalog','Шаблоны отчётов'],['builder','Конструктор'],['result','Результат'],['history','История']];
const legacyExportHref=computed(()=>{
 const query=new URLSearchParams();
 for(const [key,value] of Object.entries(props.filters))if(value!==undefined)query.set(key,String(value));
 return '/api/upts/export?'+query.toString();
});
const labels:Record<string,string>={QUEUED:'В очереди',RUNNING:'Формируется…',READY:'Готов',FAILED:'Ошибка',CANCELLED:'Отменён',EXPIRED:'Срок хранения истёк'};
const active=computed(()=>job.value&&['QUEUED','RUNNING'].includes(job.value.status));
const totalPages=(r:ReportResult)=>Math.max(1,Math.ceil((r.config.mode==='summary'?r.groups.length:r.total)/r.pageSize));
const columns=computed(()=>REPORT_COLUMNS[config.value.source]);
const currentColumns=computed(()=>config.value.columns.map(k=>columns.value.find(c=>c.key===k)!).filter(Boolean));
let alive=true,previewSerial=0,requestId=crypto.randomUUID(),pollTimer:ReturnType<typeof setTimeout>|undefined,previewTimer:ReturnType<typeof setTimeout>|undefined;
const abort=new AbortController();let previewAbort:AbortController|undefined;
const api='/api/upts/reports';const headers={'x-space-work':'1'};
function err(e:any){return e.data?.message||e.message||'Не удалось выполнить запрос.';}
async function run(fn:()=>Promise<void>){busy.value=true;error.value='';try{await fn();}catch(e){if(alive)error.value=err(e);}finally{if(alive)busy.value=false;}}
function inherit(c:ReportConfig){const f=props.filters;c.filters.projectId=Number(f.projectId)||null;c.filters.objectId=Number(f.contractId)||null;c.filters.employeeId=c.source==='documents'?null:Number(f.employeeId)||null;c.filters.q=String(f.q||'');c.filters.documentType=String(f.documentType||'');c.filters.archived=f.archived==='1';return c;}
async function loadOptions(){options.value=await $fetch<ReportOptions>(api+'/options',{query:{archived:config.value.filters.archived?'1':'0'},signal:abort.signal});}
async function loadCatalog(){templates.value=await $fetch<ReportTemplate[]>(api+'/templates',{signal:abort.signal});}
async function history(){await run(async()=>{jobs.value=await $fetch<ReportJobView[]>(api+'/jobs',{signal:abort.signal});});}
function navigate(key:string){page.value=key;if(key==='history')history();}
function start(key:string){selectedTemplate.value=null;attachments.value=false;config.value=inherit(presetReport(key));page.value='builder';tab.value='filter';requestId=crypto.randomUUID();}
function useTemplate(t:ReportTemplate){selectedTemplate.value=t;config.value=JSON.parse(JSON.stringify(t.config));if(config.value.period==='ask'){config.value.filters.from='';config.value.filters.to='';}attachments.value=false;page.value='builder';tab.value='filter';requestId=crypto.randomUUID();}
function changeSource(){const name=config.value.name,old=config.value.filters,source=config.value.source;config.value={...newReport(source),name,filters:{...old,status:'',dateField:REPORT_DATES[source][0]!.key}};attachments.value=false;}
function toggleColumn(key:string){if(config.value.columns.includes(key)){if(config.value.columns.length===1){message.value='В отчёте должен остаться хотя бы один столбец.';return;}config.value.columns=config.value.columns.filter(k=>k!==key);}else config.value.columns.push(key);}
function moveColumn(i:number,by:number){const values=config.value.columns.slice();[values[i],values[i+by]]=[values[i+by]!,values[i]!];config.value.columns=values;}
function clear(){const c=newReport(config.value.source);config.value.filters=c.filters;config.value.period='fixed';}
async function refreshPreview(p=1){const serial=++previewSerial;previewAbort?.abort();previewAbort=new AbortController();previewBusy.value=true;error.value='';try{const v=await $fetch<ReportResult>(api+'/preview',{method:'POST',headers,body:config.value,query:{page:p},signal:previewAbort.signal});if(alive&&serial===previewSerial)preview.value=v;}catch(e){if(alive&&serial===previewSerial){preview.value=null;error.value=err(e);}}finally{if(alive&&serial===previewSerial)previewBusy.value=false;}}
watch(config,()=>{requestId=crypto.randomUUID();preview.value=null;previewSerial++;previewAbort?.abort();clearTimeout(previewTimer);if(page.value==='builder')previewTimer=setTimeout(()=>refreshPreview(),450);},{deep:true});
watch(()=>config.value.filters.archived,()=>run(loadOptions));
async function poll(){if(!alive||!job.value)return;try{const id=job.value.id;const j=await $fetch<ReportJobView>(api+'/jobs/'+id,{signal:abort.signal});if(!alive||job.value?.id!==id)return;job.value=j;if(['QUEUED','RUNNING'].includes(j.status))pollTimer=setTimeout(poll,2000);else if(j.status==='READY'){message.value='Отчёт готов. Можно открыть результат или скачать файл.';await loadResult(1);}else if(j.error)error.value=j.error;}catch(e){if(alive)error.value=err(e);}}
async function generate(){await run(async()=>{clearTimeout(pollTimer);job.value=await $fetch<ReportJobView>(api+'/jobs',{method:'POST',headers,body:{config:config.value,attachments:attachments.value,requestId},signal:abort.signal});result.value=null;page.value='result';await poll();});}
async function loadResult(p:number){if(!job.value)return;await run(async()=>{result.value=await $fetch<ReportResult>(api+'/jobs/'+job.value!.id+'/result',{query:{page:p},signal:abort.signal});});}
async function selectJob(j:ReportJobView){clearTimeout(pollTimer);job.value=j;result.value=null;page.value='result';if(j.status!=='EXPIRED')await poll();}
function repeat(j:ReportJobView){config.value=JSON.parse(JSON.stringify(j.config));attachments.value=j.attachments;selectedTemplate.value=null;page.value='builder';requestId=crypto.randomUUID();}
function openSave(){templateName.value=config.value.name;shared.value=selectedTemplate.value?.shared||false;savePeriod.value=config.value.period;updateExisting.value=!!selectedTemplate.value?.canEdit;saveOpen.value=true;}
async function saveTemplate(){await run(async()=>{const old=updateExisting.value?selectedTemplate.value:null;selectedTemplate.value=await $fetch<ReportTemplate>(api+'/templates'+(old?'/'+old.id:''),{method:old?'PUT':'POST',headers,body:{config:{...config.value,name:templateName.value,period:savePeriod.value},shared:shared.value,...(old?{version:old.version}:{})},signal:abort.signal});saveOpen.value=false;message.value='Шаблон сохранён.';await loadCatalog();});}
async function removeTemplate(){if(!deleteTarget.value)return;await run(async()=>{await $fetch(api+'/templates/'+deleteTarget.value!.id,{method:'DELETE',headers,body:{version:deleteTarget.value!.version},signal:abort.signal});if(selectedTemplate.value?.id===deleteTarget.value!.id)selectedTemplate.value=null;deleteTarget.value=null;await loadCatalog();});}
async function cancel(){if(!job.value)return;await run(async()=>{await $fetch(api+'/jobs/'+job.value!.id+'/cancel',{method:'POST',headers,body:{},signal:abort.signal});message.value='Запрошена отмена. Ожидаем остановки обработки.';clearTimeout(pollTimer);await poll();});}
async function openWork(id:number){await run(async()=>{const t=await $fetch<WorkTaskDTO>('/api/work/tasks/'+id,{signal:abort.signal});emit('work',t);});}
watch(()=>props.initialJobId,id=>{if(id)run(async()=>selectJob(await $fetch<ReportJobView>(api+'/jobs/'+id,{signal:abort.signal})));});
onMounted(()=>run(async()=>{config.value=inherit(newReport());await Promise.all([loadOptions(),loadCatalog()]);if(props.initialJobId)await selectJob(await $fetch<ReportJobView>(api+'/jobs/'+props.initialJobId,{signal:abort.signal}));}));
onBeforeUnmount(()=>{alive=false;abort.abort();previewAbort?.abort();clearTimeout(pollTimer);clearTimeout(previewTimer);});
</script>
<template><Modal title="УПТС · Отчёты" subtitle="Конструктор и сохранённые шаблоны" icon="lucide:chart-no-axes-combined" full-height viewport-width fixed-sections grey-header @close="emit('close')">
<div class="upts-reports"><nav class="report-nav" aria-label="Разделы отчётов"><button v-for="n in nav" :key="n[0]" :aria-current="page===n[0]?'page':undefined" @click="navigate(n[0]!)">{{ n[1] }}</button></nav><p v-if="error" class="work-error" role="alert">{{ error }}</p><p v-if="message" class="report-notice" role="status">{{ message }} <button aria-label="Скрыть сообщение" @click="message=''">×</button></p><p v-if="busy" class="work-muted" role="status">Обрабатываем запрос…</p>
<div class="report-scroll">
<section v-if="page==='catalog'"><div class="report-heading"><h3>Готовые отчёты</h3><button class="work-primary" @click="start('works')">+ Создать отчёт</button></div><div class="report-presets"><article v-for="p in REPORT_PRESETS" :key="p.key"><h3>{{ p.name }}</h3><p>{{ p.description }}</p><button @click="start(p.key)">Настроить отчёт →</button></article></div><details class="report-legacy"><summary>Дополнительные отчёты</summary><p>Сводный Excel прежнего формата: проекты, задачи, сотрудники, участки и сооружения, объекты и параметры выборки.</p><a :href="legacyExportHref">Скачать сводный Excel</a><small>Используются фильтры основного экрана УПТС.</small></details><h3>Сохранённые шаблоны</h3><div v-if="!templates.length" class="work-muted">Ваши шаблоны появятся здесь после сохранения настроек.</div><article v-for="t in templates" :key="t.id" class="saved-report"><div><strong>{{ t.name }}</strong><small>{{ t.shared?'Общий · УПТС':'Личный' }} · {{ reportDate(t.updatedAt,true) }}</small></div><div class="work-actions"><button @click="useTemplate(t)">Открыть</button><button v-if="t.canEdit" aria-label="Удалить шаблон" @click="deleteTarget=t"><Icon name="lucide:trash-2" /></button></div></article></section>
<section v-else-if="page==='builder'"><div class="report-basics"><label>Название отчёта<input v-model="config.name" maxlength="150" /></label><label>Одна строка отчёта<select v-model="config.source" @change="changeSource"><option v-for="(label,key) in REPORT_SOURCES" :key="key" :value="key">{{ label }}</option></select></label></div>
<div class="report-layout"><div class="report-settings"><nav class="report-nav"><button v-for="t in [['filter','Выборка'],['columns','Столбцы'],['totals','Итоги']]" :key="t[0]" :aria-current="tab===t[0]?'page':undefined" @click="tab=t[0]!">{{ t[1] }}</button></nav>
<div v-if="tab==='filter'" class="report-fields"><div class="report-heading"><strong>Фильтр</strong><button @click="clear"><Icon name="lucide:filter-x" /> Очистить</button></div><label v-if="config.filters.projectId">Ограничение основного экрана<button @click="config.filters.projectId=null">Проект #{{ config.filters.projectId }} · снять</button></label><label>Объект<select v-model="config.filters.objectId"><option :value="null">Все доступные объекты</option><option v-for="o in options.objects" :key="o.id" :value="o.id">{{ o.name }}</option></select></label><label>{{ config.source==='documents'?'Добавил документ':config.source==='objects'?'Куратор, инженер или исполнитель':'Исполнитель' }}<select v-model="config.filters.employeeId"><option :value="null">Все сотрудники</option><option v-for="p in options.people" :key="p.id" :value="p.id">{{ p.name }}</option></select></label><label>Вид работ<select v-model="config.filters.kind"><option value="">Все виды</option><option v-for="k in UPTS_WORK_KINDS" :key="k.key" :value="k.key">{{ k.name }} · {{ UPTS_CONTRACT_TYPES[k.objectType] }}</option></select></label><label v-if="config.source==='works'">Состояние<select v-model="config.filters.status"><option value="">Все состояния</option><option v-for="(label,key) in WORK_STATUSES" :key="key" :value="key">{{ label }}</option><option value="CANCELLED">Отменена</option></select></label><label>Документы<select v-model="config.filters.documentType"><option value="">Все типы</option><option v-for="t in options.documentTypes" :key="t">{{ t }}</option></select></label><small v-if="config.source==='works'">Отбираются работы с документами выбранного типа.</small><label>Поиск<input v-model="config.filters.q" maxlength="200" placeholder="По значениям полей отчёта" /></label><label>Период<select v-model="config.period"><option value="fixed">Указанные даты</option><option value="month">Текущий месяц</option><option value="previousMonth">Предыдущий месяц</option><option value="ask">Запрашивать при запуске</option></select></label><label>Отбирать по дате<select v-model="config.filters.dateField"><option v-for="d in REPORT_DATES[config.source]" :key="d.key" :value="d.key">{{ d.label }}</option></select></label><div v-if="['fixed','ask'].includes(config.period)" class="report-dates"><label>С<input v-model="config.filters.from" type="date" /></label><label>По<input v-model="config.filters.to" type="date" /></label></div><small>При заданном периоде записи без выбранной даты не включаются. Даты и время — МСК.</small><label class="work-check"><input v-model="config.filters.archived" type="checkbox" />Только архивные проекты</label></div>
<div v-else-if="tab==='columns'" class="report-fields"><strong>Выберите столбцы</strong><label v-for="c in columns" :key="c.key" class="work-check"><input type="checkbox" :checked="config.columns.includes(c.key)" @change="toggleColumn(c.key)" />{{ c.label }}</label><strong>Порядок в отчёте</strong><div v-for="(c,i) in currentColumns" :key="c.key" class="report-column"><span>{{ c.label }}</span><div class="work-actions"><button :disabled="i===0" :aria-label="c.label+': выше'" @click="moveColumn(i,-1)">↑</button><button :disabled="i===currentColumns.length-1" :aria-label="c.label+': ниже'" @click="moveColumn(i,1)">↓</button></div></div></div>
<div v-else class="report-fields"><label>Группировка<select v-model="config.group"><option value="none">Без группировки</option><option value="objectStage">{{ config.source==='works'?'Объект → этап':config.source==='documents'?'Объект → тип документа':'Объект' }}</option><option value="person">{{ config.source==='works'?'Исполнитель':config.source==='documents'?'Автор загрузки':'Куратор' }}</option><option value="kind">Вид работ</option></select></label><label>Форма отчёта<select v-model="config.mode"><option value="detail">Подробный список</option><option value="summary">Сводка по группам</option></select></label><label>Порядок строк внутри группы<select v-model="config.sort"><option value="asc">Название · А → Я</option><option value="desc">Название · Я → А</option></select></label><p class="report-note">Готовность — доля выполненных работ без учёта отменённых. Просрочка — по сроку работы. Площадь и протяжённость не суммируются между собой.</p></div></div>
<div class="report-preview"><div class="report-heading"><h3>Предварительный просмотр</h3><button :disabled="previewBusy" @click="refreshPreview()"><Icon name="lucide:refresh-cw" /> Обновить</button></div><p v-if="previewBusy" class="work-muted" role="status">Обновляем выборку…</p><template v-if="preview"><p class="report-note">Объектов: {{ preview.objectCount }} · Строк: {{ preview.total }} <template v-if="config.source!=='documents'">· Выполнено: {{ preview.done }} / {{ preview.workCount }}</template></p><ReportTable :result="preview" @object="emit('object',$event)" @work="openWork" /><div class="report-pager"><button :disabled="previewBusy||preview.page<=1" @click="refreshPreview(preview.page-1)">Назад</button><span>{{ preview.page }} / {{ totalPages(preview) }}</span><button :disabled="previewBusy||preview.page>=totalPages(preview)" @click="refreshPreview(preview.page+1)">Далее</button></div></template><p v-else-if="!previewBusy" class="work-muted">Настройте выборку и нажмите «Обновить».</p></div></div></section>
<section v-else-if="page==='result'"><template v-if="job"><div class="report-heading"><div><h3>{{ job.name }}</h3><small>{{ reportDate(job.createdAt,true) }} · МСК · {{ labels[job.status] }}</small></div><button :disabled="busy" @click="repeat(job)">Изменить параметры</button></div><p v-if="job.error" class="work-error">{{ job.error }}</p><div v-if="active" class="report-note" role="status"><progress :value="job.processed" :max="Math.max(1,job.documents)" /><p>{{ labels[job.status] }} <template v-if="job.attachments">Документов: {{ job.processed }} / {{ job.documents }}.</template> Окно можно закрыть — обработка продолжится.</p><button :disabled="busy" @click="cancel">Отменить формирование</button></div><template v-if="result"><p class="report-note">Объектов: {{ result.objectCount }} · Строк: {{ result.total }} <template v-if="result.config.source!=='documents'">· Выполнено {{ result.done }} из {{ result.workCount }} · Просрочено {{ result.overdue }}</template></p><ReportTable :result="result" @object="emit('object',$event)" @work="openWork" /><div class="report-pager"><button :disabled="busy||result.page<=1" @click="loadResult(result.page-1)">Назад</button><span>{{ result.page }} / {{ totalPages(result) }}</span><button :disabled="busy||result.page>=totalPages(result)" @click="loadResult(result.page+1)">Далее</button></div></template><button v-if="!result&&job.status!=='EXPIRED'" :disabled="busy" @click="poll">Обновить состояние</button><p v-if="job.attachments" class="report-note">Распакуйте ZIP целиком в одну папку. Реестр.xlsx и подпапка «Документы» должны оставаться рядом — тогда ссылки в Excel будут работать.</p></template><p v-else class="work-muted">Выберите шаблон, настройте параметры и сформируйте отчёт.</p></section>
<section v-else><div class="report-heading"><h3>История формирования</h3><button :disabled="busy" @click="history">Обновить</button></div><p class="work-muted">Файлы и результаты доступны 24 часа; история — 30 дней. Права проверяются повторно при открытии и скачивании.</p><article v-for="j in jobs" :key="j.id" class="saved-report"><div><strong>{{ j.name }}</strong><small>{{ reportDate(j.createdAt,true) }} · {{ labels[j.status] }} · {{ j.rows }} строк</small></div><div class="work-actions"><button v-if="j.status!=='EXPIRED'" @click="selectJob(j)">Открыть</button><button @click="repeat(j)">Повторить</button></div></article><p v-if="!jobs.length&&!busy">Сформированных отчётов пока нет.</p></section>
</div>
<footer class="report-footer"><small>Только доступные вам данные · общие документы, без корзины</small><div v-if="page==='builder'" class="work-actions"><label v-if="config.source==='documents'" class="work-check"><input v-model="attachments" type="checkbox" />Документы в ZIP (до 500)</label><button :disabled="busy||!config.name.trim()" @click="openSave">Сохранить шаблон</button><button class="work-primary" :disabled="busy||previewBusy||!preview||!config.name.trim()" @click="generate">Сформировать</button></div><div v-else-if="page==='result'&&job?.status==='READY'" class="work-actions"><a :href="`${api}/jobs/${job.id}/download`">Скачать Excel</a><a v-if="job.attachments" :href="`${api}/jobs/${job.id}/download?format=zip`">Скачать ZIP с документами</a></div><button v-else @click="emit('close')">Закрыть</button></footer>
</div>
<Modal v-if="saveOpen" title="Сохранить шаблон отчёта" grey-header @close="saveOpen=false"><div class="report-save"><label>Название<input v-model="templateName" maxlength="150" /></label><label>Доступ<select v-model="shared"><option :value="false">Только мне</option><option :value="true">УПТС</option></select></label><label>Период при запуске<select v-model="savePeriod"><option value="fixed">Сохранить указанные даты</option><option value="month">Текущий месяц</option><option value="previousMonth">Предыдущий месяц</option><option value="ask">Запрашивать перед формированием</option></select></label><label v-if="selectedTemplate?.canEdit" class="work-check"><input v-model="updateExisting" type="checkbox" />Обновить открытый шаблон</label><p class="work-muted">Общий шаблон не расширяет права доступа к объектам. Изменить и удалить его может автор или администратор.</p><p v-if="error" class="work-error" role="alert">{{ error }}</p><div class="work-actions"><button class="work-primary" :disabled="busy||!templateName.trim()" @click="saveTemplate">Сохранить</button><button :disabled="busy" @click="saveOpen=false">Отмена</button></div></div></Modal>
<Modal v-if="deleteTarget" title="Удалить шаблон?" grey-header @close="deleteTarget=null"><p>{{ deleteTarget.name }}</p><p>Сформированные отчёты останутся в истории.</p><p v-if="error" class="work-error">{{ error }}</p><div class="work-actions"><button :disabled="busy" @click="removeTemplate">Удалить</button><button :disabled="busy" @click="deleteTarget=null">Отмена</button></div></Modal>
</Modal></template>
<style scoped>
.report-legacy{margin:0 0 20px;padding:10px 0;border-bottom:1px solid var(--work-line)}.report-legacy summary{color:var(--work-muted);cursor:pointer}.report-legacy p{margin:8px 0}.report-legacy a{color:var(--work-accent);text-decoration:underline}.report-legacy small{display:block;margin:6px 0}

